def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except Exception as exc:
        raise TypeError(f"Cannot dehydrate value of type {type(value).__name__}: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    # Attempt to extract coordinates
    try:
        x = getattr(value, 'x')
        y = getattr(value, 'y')
    except AttributeError as e:
        raise TypeError("value must have 'x' and 'y' attributes") from e
    # Build a serializable representation
    result = {'x': x, 'y': y}
    # Include optional z coordinate if present
    if hasattr(value, 'z'):
        try:
            result['z'] = getattr(value, 'z')
        except Exception as e:
            # If z extraction fails, ignore it
            pass
    return result

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated data dictionary if present
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())
        # Fallback to a fields list/tuple if present
        if hasattr(self, "fields") and isinstance(self.fields, (list, tuple)):
            return list(self.fields)
        # As a last resort, expose public attributes from __dict__
        return [k for k in self.__dict__ if not k.startswith("_")]
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve keys: {exc}") from exc

def index(self, key):
        """ Return the index of the given item.

        :param key: a key
        :return: index
        :rtype: int
        """
        # Attempt to retrieve the underlying sequence that holds the items.
        # Prefer a private attribute, fall back to a public one if necessary.
        data = getattr(self, "_data", None)
        if data is None:
            data = getattr(self, "data", None)
        if data is None:
            raise AttributeError("The object does not contain a '_data' or 'data' attribute to search.")

        # Ensure the data is a sequence that supports indexing.
        if not isinstance(data, (list, tuple)):
            raise TypeError("The '_data' or 'data' attribute must be a list or tuple to use index().")

        try:
            return data.index(key)
        except ValueError:
            raise ValueError(f"Key {key!r} not found in the collection.")
        except Exception as exc:
            # Catch any other unexpected errors and re-raise as a RuntimeError
            raise RuntimeError(f"An unexpected error occurred while searching for key {key!r}: {exc}") from exc

def data(self, *keys):
        """
        Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Assume the record stores keys and values in parallel lists
        # named `_keys` and `_values`.  If these attributes are not
        # present, an AttributeError will be raised naturally.
        if not keys:
            # Return all key/value pairs
            return dict(zip(self._keys, self._values))

        result = {}
        for key in keys:
            if isinstance(key, int):
                # Treat as an index into the record
                try:
                    name = self._keys[key]
                    value = self._values[key]
                except IndexError:
                    raise IndexError(f"Index {key} out of bounds") from None
                result[name] = value
            else:
                # Treat as a key name
                if key in self._keys:
                    idx = self._keys.index(key)
                    result[key] = self._values[idx]
                else:
                    result[key] = None
        return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an int, got {type(qid).__name__}")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")

    # Validate hook dictionaries
    for hook_dict, name in ((dehydration_hooks, "dehydration_hooks"),
                            (hydration_hooks, "hydration_hooks")):
        if hook_dict:
            for key, func in hook_dict.items():
                if not isinstance(key, type):
                    raise TypeError(f"Keys in {name} must be types, got {type(key).__name__}")
                if not callable(func):
                    raise TypeError(f"Values in {name} must be callables, got {type(func).__name__}")

    # Construct the DISCARD message
    message = {
        "type": "DISCARD",
        "n": n,
        "qid": qid
    }

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError as exc:
        raise AttributeError("The object does not have an '_output_queue' attribute.") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to append DISCARD message to output queue: {exc}") from exc

    # Prepare kwargs for Response
    response_kwargs = handlers.copy()
    if dehydration_hooks is not None:
        response_kwargs["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        response_kwargs["hydration_hooks"] = hydration_hooks

    # Create and return the Response object
    try:
        return Response(message, **response_kwargs)
    except Exception as exc:
        raise RuntimeError(f"Failed to create Response object: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is not None:
            if not isinstance(mode, str):
                raise TypeError(f"mode must be a string, got {type(mode).__name__}")
            mode_upper = mode.upper()
            if mode_upper not in ("READ", "WRITE"):
                raise ValueError(f"mode must be 'READ' or 'WRITE', got '{mode}'")
            mode = mode_upper

        # Validate bookmarks
        if bookmarks is not None:
            try:
                bookmarks_list = list(bookmarks)
            except TypeError:
                raise TypeError("bookmarks must be an iterable of bookmark strings")
            for bm in bookmarks_list:
                if not isinstance(bm, str):
                    raise TypeError(f"each bookmark must be a string, got {type(bm).__name__}")
        else:
            bookmarks_list = None

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError(f"metadata must be a dict, got {type(metadata).__name__}")

        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise TypeError(f"timeout must be a number, got {type(timeout).__name__}")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise TypeError(f"db must be a string, got {type(db).__name__}")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError(f"imp_user must be a string, got {type(imp_user).__name__}")

        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
            for key, func in dehydration_hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"dehydration_hooks keys must be types, got {type(key).__name__}")
                if not callable(func):
                    raise TypeError(f"dehydration_hooks values must be callables, got {type(func).__name__}")
        else:
            dehydration_hooks = {}

        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")
            for key, func in hydration_hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"hydration_hooks keys must be types, got {type(key).__name__}")
                if not callable(func):
                    raise TypeError(f"hydration_hooks values must be callables, got {type(func).__name__}")
        else:
            hydration_hooks = {}

        # Build the BEGIN message
        message = {
            "type": "BEGIN",
            "mode": mode,
            "bookmarks": bookmarks_list,
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks
        }

        # Append to the output queue
        try:
            self._output_queue.append(message)
        except AttributeError as e:
            raise RuntimeError("Output queue not initialized") from e
        except Exception as e:
            raise RuntimeError("Failed to append BEGIN message to output queue") from e

        # Return a Response object
        try:
            return Response(message, **handlers)
        except Exception as e:
            raise RuntimeError("Failed to create Response object") from e

def hashkey(*args, **kwargs):
    """Generate a hashable key from function arguments."""
    try:
        # Use args tuple and sorted kwargs items to form a hashable key
        return (args, tuple(sorted(kwargs.items())))
    except Exception:
        # Fallback to string representations if any part is unhashable
        return (repr(args), repr(kwargs))

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if cache is None:
        raise TypeError("cache must not be None")
    if not hasattr(cache, "__getitem__") or not hasattr(cache, "__setitem__"):
        raise TypeError("cache must support __getitem__ and __setitem__")
    if lock is not None and not (hasattr(lock, "acquire") or hasattr(lock, "__enter__")):
        raise TypeError("lock must support acquire/release or be a context manager")
    key_func = key if key is not None else hashkey

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key_func(*args, **kwargs)
            except Exception as e:
                raise RuntimeError("Key function raised an exception") from e

            # Acquire lock if provided
            if lock is not None:
                if hasattr(lock, "acquire"):
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                    finally:
                        lock.release()
                else:
                    # Assume lock is a context manager
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        cache = {}  # key -> (value, count)

        def wrapper(*args, **kwargs):
            # Attempt to build a hashable key
            try:
                if typed:
                    key = (
                        args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(arg) for arg in args),
                        tuple(type(v) for v in kwargs.values()),
                    )
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except TypeError:
                # If arguments are unhashable, skip caching
                return func(*args, **kwargs)

            # Check cache
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value

            # Compute result
            try:
                value = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise

            # Add to cache, evict if necessary
            if len(cache) >= maxsize:
                # Find key with lowest usage count
                min_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        min_key = k
                if min_key is not None:
                    del cache[min_key]

            cache[key] = (value, 1)
            return value

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    value = self.pop(first_key)
    return (first_key, value)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        if key in self:
            return self[key]
    except Exception:
        return default
    return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise ValueError("cache must not be None")
    if key is None:
        def default_hashkey(func, *args, **kwargs):
            return (func, args, frozenset(kwargs.items()))
        key_func = default_hashkey
    else:
        if not callable(key):
            raise TypeError("key must be callable")
        key_func = key
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key_func(func, *args, **kwargs)
            if lock:
                lock.acquire()
            try:
                try:
                    return cache[k]
                except KeyError:
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            finally:
                if lock:
                    lock.release()
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
    except ImportError as exc:
        raise RuntimeError("zope.interface is required for directlyProvidedBy") from exc
    try:
        return _directlyProvidedBy(object)
    except Exception:
        # Return an empty IDeclaration for invalid inputs
        return _directlyProvidedBy(object())

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate that `classes` is iterable
    try:
        iter(classes)
    except TypeError:
        raise TypeError("`classes` must be an iterable of classes")

    result = []
    for base in classes:
        # Ensure each element is a class
        if not isinstance(base, type):
            raise TypeError(f"Element {base!r} is not a class")

        # Skip if `base` is a subclass of any class already in `result`
        skip = False
        for existing in result:
            try:
                if issubclass(base, existing):
                    skip = True
                    break
            except TypeError:
                # Should not happen because both are classes, but treat as skip
                skip = True
                break
        if skip:
            continue

        # Remove any classes in `result` that are subclasses of the new `base`
        new_result = []
        for existing in result:
            try:
                if not issubclass(existing, base):
                    new_result.append(existing)
            except TypeError:
                # Keep the class if subclass check fails
                new_result.append(existing)
        result = new_result

        # Append the new base
        result.append(base)

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a bool")
    try:
        import inspect
        result = []
        if all:
            # Include attributes from the class and its bases
            for name, obj in inspect.getmembers(self.__class__):
                if name.startswith('_'):
                    continue
                if inspect.isroutine(obj):
                    continue
                if isinstance(obj, property):
                    doc = obj.fget.__doc__
                else:
                    doc = getattr(obj, "__doc__", None)
                result.append((name, doc or ""))
        else:
            # Only attributes defined directly in this class
            for name, obj in self.__class__.__dict__.items():
                if name.startswith('_'):
                    continue
                if inspect.isroutine(obj):
                    continue
                if isinstance(obj, property):
                    doc = obj.fget.__doc__
                else:
                    doc = getattr(obj, "__doc__", None)
                result.append((name, doc or ""))
        return result
    except Exception as exc:
        raise RuntimeError(f"Error retrieving names and descriptions: {exc}") from exc

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Ensure output is a list-like container
    if output is None:
        output = []
    elif not hasattr(output, "append"):
        raise TypeError("output must be a list or list-like object")

    # Helper to process a single item
    def _process(item):
        # Treat tuples as implements specs (keep as is)
        if isinstance(item, tuple):
            output.append(item)
            return
        # Treat strings and bytes as individual interfaces
        if isinstance(item, (str, bytes)):
            output.append(item)
            return
        # If item is a mapping, iterate over its values
        if isinstance(item, dict):
            for val in item.values():
                _process(val)
            return
        # If item is an iterable (but not string/bytes/tuple), expand it
        try:
            iter(item)
        except TypeError:
            # Not iterable, treat as individual interface
            output.append(item)
            return
        # For other iterables (list, set, generator, etc.), recurse
        for sub in item:
            _process(sub)

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # If sequence itself is a tuple, treat as implements spec
    if isinstance(sequence, tuple):
        output.append(sequence)
        return output

    # If sequence is a mapping, iterate over its values
    if isinstance(sequence, dict):
        for val in sequence.values():
            _process(val)
        return output

    # If sequence is an iterable (list, set, generator, etc.), process each element
    try:
        iter(sequence)
    except TypeError:
        # Not iterable, treat as single interface
        output.append(sequence)
        return output

    for elem in sequence:
        _process(elem)

    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
    except NameError:
        # If the required function is not defined, assume optimizations are ignored
        return True
    except Exception:
        # Any other error while determining requirement, default to ignored
        return True
    # Return the logical negation of the required flag, ensuring a boolean result
    return not bool(required)

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True, we do not need C optimizations.
        # Otherwise, C optimizations are required.
        return bool(not PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are not required.
        return False

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context
        try:
            self._context = {}
        except AttributeError:
            # If the attribute does not exist, create it
            self._context = {}

        # Reinitialize bins
        # Prefer initial_value if it is defined (even if None)
        if hasattr(self, "_initial_value") and self._initial_value is not None:
            # If bins already exist, set each to the initial value
            if hasattr(self, "_bins"):
                try:
                    if isinstance(self._bins, dict):
                        for key in self._bins:
                            self._bins[key] = self._initial_value
                    elif isinstance(self._bins, (list, tuple)):
                        for i in range(len(self._bins)):
                            self._bins[i] = self._initial_value
                    else:
                        # Fallback: replace with a new dict
                        self._bins = {k: self._initial_value for k in self._bins}
                except Exception:
                    # If something goes wrong, replace bins entirely
                    self._bins = {}
            else:
                # No bins yet, create an empty dict
                self._bins = {}
        # If no initial_value, try to use make_bins if available
        elif hasattr(self, "_make_bins") and callable(self._make_bins):
            try:
                self._bins = self._make_bins()
            except Exception as exc:
                raise RuntimeError("make_bins() raised an exception during reset") from exc
        else:
            # No way to reinitialize bins
            raise RuntimeError("Histogram cannot be reset: no initial_value or make_bins defined")

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Prepare output lines
    lines = []
    if header is not None:
        lines.append(str(header))
    # Retrieve points from the graph
    try:
        points = self.points
    except AttributeError:
        points = self
    for point in points:
        # Unpack coordinate and value
        try:
            coord, value = point
        except Exception:
            coord = point
            value = None
        # Process coordinate
        if coord is None:
            coord_parts = []
        elif isinstance(coord, (str, bytes)):
            coord_parts = [coord]
        elif hasattr(coord, "__iter__"):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]
        # Process value
        if value is None:
            value_parts = []
        elif isinstance(value, (str, bytes)):
            value_parts = [value]
        elif isinstance(value, dict):
            value_parts = [str(v) for v in value.values()]
        elif hasattr(value, "__iter__"):
            value_parts = [str(v) for v in value]
        else:
            value_parts = [str(value)]
        # Combine parts
        line_parts = coord_parts + value_parts
        lines.append(separator.join(line_parts))
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the error indices mapping exists
    try:
        err_map = self._err_indices
    except AttributeError:
        raise AttributeError("The object does not have an '_err_indices' attribute")

    # Retrieve indices for the requested coordinate
    try:
        indices = err_map[coord_name]
    except KeyError:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices")

    # Normalise the result to a list
    if indices is None:
        return []

    try:
        return list(indices)
    except Exception as exc:
        raise TypeError(f"Error indices for '{coord_name}' must be iterable, got {type(indices).__name__}") from exc

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        import numpy as np
        bins_arr = np.asarray(bins, dtype=float)

        # 1D histogram
        if not isinstance(edges, (list, tuple)):
            edges_arr = np.asarray(edges, dtype=float)
            if edges_arr.ndim != 1:
                raise ValueError("Edges must be a 1D array for a 1D histogram.")
            widths = np.diff(edges_arr)
            if widths.size != bins_arr.size:
                raise ValueError("Number of bins does not match number of edges.")
            return float(np.sum(bins_arr * widths))

        # Multi‑dimensional histogram
        if len(edges) != bins_arr.ndim:
            raise ValueError("Number of edge arrays must match histogram dimensions.")
        widths = [np.diff(np.asarray(e, dtype=float)) for e in edges]
        width_prod = np.ones_like(bins_arr, dtype=float)
        for i, w in enumerate(widths):
            shape = [1] * bins_arr.ndim
            shape[i] = -1
            width_prod *= w.reshape(shape)
        return float(np.sum(bins_arr * width_prod))

    except Exception as exc:
        raise ValueError(f"Failed to compute integral: {exc}") from exc

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Direct instance check
        if isinstance(seq, FillRequest):
            return True
        # Exclude string/bytes which are iterable but not sequences of elements
        if isinstance(seq, (str, bytes)):
            return False
        # Exclude a Source instance itself
        if isinstance(seq, Source):
            return False
        # Iterate over the sequence to find a FillRequest
        has_fill = False
        has_non_source = False
        for item in seq:
            if isinstance(item, FillRequest):
                has_fill = True
            if not isinstance(item, Source):
                has_non_source = True
        if has_fill:
            return True
        # If all items are Source, it's a Source sequence
        if not has_non_source:
            return False
        return False
    except TypeError:
        # seq is not iterable
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            hasattr(obj, "fill")
            and callable(getattr(obj, "fill"))
            and hasattr(obj, "request")
            and callable(getattr(obj, "request"))
        )
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")

    def _diff(a, b, lvl):
        result = {}
        for key, val in a.items():
            if key not in b:
                # key only in a
                # if val is a dict, we can return it directly
                result[key] = val
            else:
                val_b = b[key]
                if isinstance(val, dict) and isinstance(val_b, dict):
                    # both are dicts
                    if lvl == 0:
                        # no further recursion
                        if val != val_b:
                            result[key] = val
                    else:
                        # recurse
                        next_lvl = lvl - 1 if lvl > 0 else -1
                        subdiff = _diff(val, val_b, next_lvl)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # non-dict values
                    if val != val_b:
                        result[key] = val
        return result

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Validate weight
        try:
            weight = float(weight)
        except Exception as exc:
            raise TypeError(f"Weight must be a numeric value, got {type(weight).__name__}") from exc

        # Convert coord to a list of floats
        try:
            coord = list(coord)
        except Exception as exc:
            raise TypeError(f"Coordinate must be an iterable, got {type(coord).__name__}") from exc

        # Check dimensionality
        if len(coord) != len(self.edges):
            raise ValueError(f"Coordinate dimensionality {len(coord)} does not match histogram dimensions {len(self.edges)}")

        # Find bin indices for each dimension
        indices = []
        for dim, (edge, c) in enumerate(zip(self.edges, coord)):
            # Edge must be a sequence of bin edges
            if not hasattr(edge, "__len__"):
                raise TypeError(f"Edges for dimension {dim} must be a sequence, got {type(edge).__name__}")
            # Use searchsorted to find the right bin
            try:
                idx = np.searchsorted(edge, c, side='right') - 1
            except Exception as exc:
                raise ValueError(f"Failed to locate coordinate {c} in edges for dimension {dim}") from exc
            # Check bounds
            if idx < 0 or idx >= len(edge) - 1:
                # Coordinate is outside histogram edges; ignore
                return
            indices.append(idx)

        # Increment the histogram bin
        try:
            self.hist[tuple(indices)] += weight
        except Exception as exc:
            raise RuntimeError(f"Failed to update histogram bin at indices {indices}") from exc

