def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Safely access the manifest list
        manifest = getattr(app, "spec", None)
        if manifest is None:
            return {}
        manifest = getattr(manifest, "manifest", None)
        if manifest is None:
            return {}

        # Custom observer schemas, if any
        custom_schema = getattr(app.spec, "observer_schema", {})
        if not isinstance(custom_schema, dict):
            custom_schema = {}

        default_schema = {}
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            # Skip kinds that already have a custom schema
            if kind in custom_schema:
                continue
            # Build a minimal default schema
            schema = {
                "type": "object",
                "properties": {
                    "metadata": {"type": "object"},
                    "status": {"type": "object"},
                },
                "required": ["metadata"],
            }
            default_schema[kind] = schema

        return default_schema
    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            # Resolve the root directory from the input
            if isinstance(path, str):
                root_dir = path
            elif hasattr(path, "path") and isinstance(path.path, str):
                root_dir = path.path
            else:
                return False

            # Basic existence checks
            if not os.path.isdir(root_dir):
                return False

            # Required OCFL metadata files
            ocfl_version_file = os.path.join(root_dir, ".ocfl_version")
            ocfl_root_file = os.path.join(root_dir, ".ocfl_root")

            if not os.path.isfile(ocfl_version_file):
                return False
            if not os.path.isfile(ocfl_root_file):
                return False

            # Read the root directory name from .ocfl_root
            try:
                with open(ocfl_root_file, "r", encoding="utf-8") as f:
                    root_subdir = f.read().strip()
            except Exception:
                return False

            if not root_subdir:
                return False

            # Verify that the declared root subdirectory exists
            full_root_path = os.path.join(root_dir, root_subdir)
            if not os.path.isdir(full_root_path):
                return False

            # Check for the presence of the objects directory
            objects_path = os.path.join(full_root_path, "objects")
            if not os.path.isdir(objects_path):
                return False

            # All basic checks passed; return True
            return True
        except Exception:
            # Any unexpected error results in a validation failure
            return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate prefix
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Attempt to retrieve status; handle any attribute errors gracefully
    try:
        status = getattr(self, 'status')
    except Exception:
        status = None
    # If status is None, return just the prefix
    if status is None:
        return prefix
    # Convert status to string safely
    try:
        status_str = str(status)
    except Exception:
        status_str = "<unrepresentable status>"
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Validate prefix
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Retrieve the log attribute; fall back to common names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)
    if log is None:
        return ''
    # If the log itself is a string, treat it as a single entry
    if isinstance(log, str):
        return f"{prefix}{log}"
    # If the log is a dictionary, format key: value pairs
    if isinstance(log, dict):
        lines = [f"{prefix}{k}: {v}" for k, v in log.items()]
        return "\n".join(lines)
    # If the log is an iterable (list, tuple, set, etc.), format each entry
    try:
        iterator = iter(log)
    except TypeError:
        # Not iterable; return its string representation
        return f"{prefix}{str(log)}"
    # Avoid treating strings as iterables of characters
    if isinstance(log, (list, tuple, set)):
        lines = [f"{prefix}{entry}" for entry in iterator]
        return "\n".join(lines)
    # Fallback: treat as a single entry
    return f"{prefix}{str(log)}"

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check for inventory
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine the spec version to use
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("Instance does not have a 'spec_version' attribute.")

        if extract_spec_version:
            # Map known type values to spec versions
            type_to_version = {
                "typeA": "1.0",
                "typeB": "2.0",
                # Add more mappings as needed
            }
            inv_type = inventory.get("type")
            if inv_type in type_to_version:
                spec_version = type_to_version[inv_type]
            # If type is missing or unknown, keep the default spec_version

        # Perform validation based on the determined spec version
        try:
            if spec_version.startswith("1"):
                # Version 1.x expects 'name' (string) and 'items' (list)
                if "name" not in inventory or not isinstance(inventory["name"], str):
                    return False
                if "items" not in inventory or not isinstance(inventory["items"], list):
                    return False
            elif spec_version.startswith("2"):
                # Version 2.x expects 'title' (string) and 'components' (list)
                if "title" not in inventory or not isinstance(inventory["title"], str):
                    return False
                if "components" not in inventory or not isinstance(inventory["components"], list):
                    return False
            else:
                # Unknown spec version
                return False
        except Exception:
            # Any unexpected error during validation results in a failed validation
            return False

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate digests_used type
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple of digests.")
    digests_used_set = set(digests_used)

    # Prepare a set to collect all digests found in the manifest(s)
    manifest_digests = set()

    # Handle two possible forms of manifest_files:
    # 1. A dictionary mapping file names to digests.
    # 2. A list of file paths containing digest information.
    if isinstance(manifest_files, dict):
        for file_name, digest in manifest_files.items():
            if digest is None:
                continue
            manifest_digests.add(digest)
    elif isinstance(manifest_files, list):
        for path in manifest_files:
            if not isinstance(path, str):
                raise TypeError("Each manifest file path must be a string.")
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    for line in f:
                        line = line.strip()
                        if not line or line.startswith('#'):
                            continue
                        # Expect format: <filename>: <digest>
                        if ':' not in line:
                            continue
                        _, digest = line.split(':', 1)
                        digest = digest.strip()
                        if digest:
                            manifest_digests.add(digest)
            except FileNotFoundError as e:
                raise FileNotFoundError(f"Manifest file not found: {path}") from e
            except Exception as e:
                raise ValueError(f"Error reading manifest file {path}: {e}") from e
    else:
        raise TypeError("manifest_files must be a dict or a list of file paths.")

    # Check that all digests used are present in the manifest
    missing_in_manifest = digests_used_set - manifest_digests
    if missing_in_manifest:
        raise ValueError(f"Digests used but not present in manifest: {missing_in_manifest}")

    # Optionally, check that all digests in the manifest are used
    unused_in_manifest = manifest_digests - digests_used_set
    if unused_in_manifest:
        raise ValueError(f"Digests present in manifest but not used: {unused_in_manifest}")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if fixity is None:
        raise ValueError("Fixity block is missing.")
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dictionary, got {type(fixity).__name__}.")

    if manifest_files is None:
        raise ValueError("Manifest files list is missing.")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("Manifest files must be an iterable of file paths.")

    # Validate each entry in the fixity block
    for path, value in fixity.items():
        if not isinstance(path, str):
            raise ValueError(f"Fixity key must be a string file path, got {type(path).__name__}.")

        if path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{path}' not in manifest.")

        # Extract the hash value
        if isinstance(value, dict):
            if 'hash' not in value:
                raise ValueError(f"Fixity entry for '{path}' must contain a 'hash' key.")
            hash_val = value['hash']
        else:
            hash_val = value

        if not isinstance(hash_val, str):
            raise ValueError(f"Hash for file '{path}' must be a string, got {type(hash_val).__name__}.")
        if not hash_val:
            raise ValueError(f"Hash for file '{path}' is empty.")
        if not all(c in '0123456789abcdefABCDEF' for c in hash_val):
            raise ValueError(f"Hash for file '{path}' contains non-hex characters.")

    return True

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string")
    os = __import__('os')
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder {folder} does not exist or is not a directory")
    try:
        entries = os.listdir(folder)
    except OSError as e:
        raise RuntimeError(f"Error accessing folder {folder}: {e}") from e
    files = [f for f in entries if os.path.isfile(os.path.join(folder, f))]
    xml_basenames = set()
    for f in files:
        if f.lower().endswith('.xml'):
            xml_basenames.add(os.path.splitext(f)[0])
    data = {}
    for basename in xml_basenames:
        group = []
        for f in files:
            if os.path.splitext(f)[0] == basename:
                group.append(os.path.join(folder, f))
        group.sort()
        data[basename] = group
    return data

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate inputs
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("lang must be a non-empty string")
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("file_path must be a non-empty string")
    # Initialize renditions dict if not present
    if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
        self.renditions = {}
    # Add or update the rendition
    try:
        self.renditions[lang] = file_path
    except Exception as exc:
        raise RuntimeError(f"Failed to add rendition for language '{lang}': {exc}") from exc
    return None

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path to a zip file")

    xml_basenames = set()
    file_infos = []

    # First pass: collect XML basenames and file infos
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                file_infos.append(info)
                if info.filename.lower().endswith('.xml'):
                    xml_basenames.add(os.path.splitext(os.path.basename(info.filename))[0])
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error reading zip file {zip_path}: {e}") from e

    # Second pass: group files by XML basename
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in file_infos:
                basename = os.path.splitext(os.path.basename(info.filename))[0]
                if basename in xml_basenames:
                    if basename not in result:
                        result[basename] = {}
                    try:
                        data = zf.read(info)
                    except Exception:
                        data = None
                    result[basename][info.filename] = data
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise ValueError(f"An error occurred while processing the content: {e}") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the result is a string (e.g., from an XPath that returns a string)
                if isinstance(first, str):
                    return first.strip()
                # If the result is an element, try to extract its text
                text = first.text
                if text is None:
                    # Fallback to the string value of the element
                    text = first.xpath('string()')
                if text:
                    return text.strip()
        except Exception:
            # Ignore any errors and continue with the next xpath
            continue
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    # In Python 3 the API already returns unicode, so just return the original function
    if sys.version_info[0] >= 3:
        return namefunc

    # Python 2: wrap the function to ensure it returns a bytestring
    try:
        unicode_type = unicode  # noqa: F821
    except NameError:
        unicode_type = str

    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # Only encode if the result is a unicode string (not a bytestring)
        if isinstance(result, unicode_type) and not isinstance(result, bytes):
            try:
                return result.encode('utf-8')
            except Exception:
                # If encoding fails, fall back to the original result
                return result
        return result

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to import importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata as importlib_metadata
    except Exception:
        # Fallback to importlib_metadata backport if available
        try:
            import importlib_metadata
        except Exception:
            return "0.0.0"

    # Determine the package name from the current module's package context
    pkg_name = __package__
    if not pkg_name:
        return "0.0.0"

    # Try to fetch the version; return a default if any error occurs
    try:
        return importlib_metadata.version(pkg_name)
    except Exception:
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate and normalize pieces
    if pieces is None:
        return ''
    if isinstance(pieces, str):
        # Treat a string as a single piece
        pieces_list = [pieces]
    else:
        try:
            pieces_list = list(pieces)
        except TypeError:
            raise TypeError("pieces must be an iterable of version components") from None
    # Convert each piece to string, handling non-stringifiable elements
    try:
        str_pieces = [str(p) for p in pieces_list]
    except Exception as e:
        raise ValueError("pieces contain non-stringifiable elements") from e
    # Validate style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    # Render according to style
    if style == 'semver':
        return '.'.join(str_pieces)
    elif style == 'pep440':
        # Drop trailing zeros
        idx = len(str_pieces) - 1
        while idx >= 0 and str_pieces[idx] == '0':
            idx -= 1
        return '.'.join(str_pieces[:idx + 1]) if idx >= 0 else '0'
    elif style == 'short':
        return '.'.join(str_pieces[:2]) if len(str_pieces) >= 2 else '.'.join(str_pieces)
    elif style == 'json':
        import json
        return json.dumps(str_pieces)
    elif style == 'none':
        return ''
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # If pieces is a string or any iterable, check for the presence of '+'
        if '+' in pieces:
            return '.'
        else:
            return '+'
    except Exception as exc:
        raise TypeError("pieces must be an iterable containing characters") from exc

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    if not callable(method):
        raise TypeError("method must be a callable")

    # Attach metadata to the method
    setattr(method, "_vcs_handler", vcs)

    # Register the handler in a module-level registry
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    register_vcs_handler._registry[vcs] = method

    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Validate input types
        if not isinstance(validate_objects, bool):
            raise TypeError(f"validate_objects must be a bool, got {type(validate_objects).__name__}")
        if not isinstance(check_digests, bool):
            raise TypeError(f"check_digests must be a bool, got {type(check_digests).__name__}")
        if not isinstance(show_warnings, bool):
            raise TypeError(f"show_warnings must be a bool, got {type(show_warnings).__name__}")

        # Retrieve the collection of objects to validate
        objects = getattr(self, 'objects', None)
        if objects is None:
            objects = getattr(self, '_objects', None)
        if objects is None:
            raise AttributeError("The object has no 'objects' or '_objects' attribute to validate.")

        # Ensure the objects collection is iterable
        try:
            iterator = iter(objects)
        except TypeError:
            raise TypeError(f"The 'objects' attribute is not iterable (type: {type(objects).__name__})")

        num_objects = 0
        good_objects = 0

        for obj in iterator:
            num_objects += 1
            obj_valid = True
            # Validate the object itself if requested
            if validate_objects:
                if hasattr(obj, 'validate') and callable(getattr(obj, 'validate')):
                    try:
                        result = obj.validate()
                        if not bool(result):
                            obj_valid = False
                            if show_warnings:
                                print(f"Warning: Object {repr(obj)} failed validation.")
                    except Exception as e:
                        obj_valid = False
                        if show_warnings:
                            print(f"Warning: Exception during validation of {repr(obj)}: {e}")
                else:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: Object {repr(obj)} has no callable 'validate' method.")
            # Check the digest if requested
            if check_digests:
                if hasattr(obj, 'check_digest') and callable(getattr(obj, 'check_digest')):
                    try:
                        result = obj.check_digest()
                        if not bool(result):
                            obj_valid = False
                            if show_warnings:
                                print(f"Warning: Object {repr(obj)} failed digest check.")
                    except Exception as e:
                        obj_valid = False
                        if show_warnings:
                            print(f"Warning: Exception during digest check of {repr(obj)}: {e}")
                else:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: Object {repr(obj)} has no callable 'check_digest' method.")
            if obj_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
        """
        Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        if not version_dirs:
            return {}

        # Helper to load an inventory file into a dict {path: digest}
        def _load_inventory(inv_path):
            inv = {}
            try:
                with open(inv_path, 'r', encoding='utf-8') as f:
                    for line in f:
                        line = line.strip()
                        if not line or line.startswith('#'):
                            continue
                        parts = line.split(None, 1)
                        if len(parts) != 2:
                            continue  # skip malformed lines
                        path, digest = parts
                        inv[path] = digest
            except Exception as e:
                raise IOError(f"Failed to read inventory '{inv_path}': {e}") from e
            return inv

        # Load root inventory if not already available
        if hasattr(self, 'root_inventory') and isinstance(self.root_inventory, dict):
            root_inv = self.root_inventory
        else:
            if not hasattr(self, 'root_inventory_path'):
                raise AttributeError("root_inventory_path attribute is required to load root inventory")
            root_inv = _load_inventory(self.root_inventory_path)
            self.root_inventory = root_inv  # cache for future use

        # Record of differing digests: {path: [list of version dirs where it differs]}
        differing_digests = {}

        for ver_dir in version_dirs:
            # Determine inventory file path; assume 'inventory.txt' in each version dir
            inv_path = os.path.join(ver_dir, 'inventory.txt')
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(f"Inventory file not found for version directory '{ver_dir}': {inv_path}")

            ver_inv = _load_inventory(inv_path)

            # Check each entry in the version inventory against the root inventory
            for path, ver_digest in ver_inv.items():
                root_digest = root_inv.get(path)
                if root_digest is None:
                    # Path not present in root inventory; skip or record as needed
                    continue
                if ver_digest != root_digest:
                    differing_digests.setdefault(path, []).append(ver_dir)

            # Optionally, check for missing entries in the version inventory
            # (i.e., entries present in root but missing in this version)
            # This is not strictly required by the docstring but can be useful
            # for detecting incomplete inventories.
            # for path in root_inv:
            #     if path not in ver_inv:
            #         raise ValueError(f"Missing inventory entry for '{path}' in version directory '{ver_dir}'")

        # Store the differences for later validation if needed
        self.differing_digests = differing_digests
        return differing_digests

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')

    def is_mapping_node(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_values(a_vals, b_vals):
        # a_vals and b_vals are lists of (ScalarNode, Node) tuples
        result = list(a_vals)
        key_index = {getattr(k, 'value', None): i for i, (k, _) in enumerate(a_vals)}
        for key_node, val_node in b_vals:
            key = getattr(key_node, 'value', None)
            if key is None:
                continue
            if key in key_index:
                idx = key_index[key]
                existing_key_node, existing_val_node = result[idx]
                if is_mapping_node(val_node) and is_mapping_node(existing_val_node):
                    merged_vals = merge_mapping_values(existing_val_node.value, val_node.value)
                    # Reconstruct the MappingNode with the same tag
                    merged_node = type(existing_val_node)(existing_val_node.tag, merged_vals)
                    result[idx] = (existing_key_node, merged_node)
                else:
                    # last wins
                    result[idx] = (existing_key_node, val_node)
            else:
                result.append((key_node, val_node))
                key_index[key] = len(result) - 1
        return result

    result = []
    key_index = {}
    for key_node, val_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            continue
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_val_node = result[idx]
            if is_mapping_node(val_node) and is_mapping_node(existing_val_node):
                merged_vals = merge_mapping_values(existing_val_node.value, val_node.value)
                merged_node = type(existing_val_node)(existing_val_node.tag, merged_vals)
                result[idx] = (existing_key_node, merged_node)
            else:
                result[idx] = (existing_key_node, val_node)
        else:
            key_index[key] = len(result)
            result.append((key_node, val_node))
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # Attempt to access the internal actions list
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    # Collect all option strings from each action
    flags = []
    for action in actions:
        # Some actions (e.g., positional arguments) may not have option_strings
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)
    # Return a space‑separated string of flags
    return " ".join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")
    if not isinstance(unparsed_arguments, (list, tuple)):
        # Try to convert to list
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception as exc:
            raise TypeError("unparsed_arguments must be a sequence of strings") from exc

    # Helper to compute indices of remaining tokens
    def _remaining_indices(original, remaining):
        indices = set()
        j = 0
        for i, token in enumerate(original):
            if j < len(remaining) and token == remaining[j]:
                indices.add(i)
                j += 1
        return indices

    namespace_map = {}
    remaining_indices_per_parser = []

    # If no subparsers, all arguments are unclaimed
    if not subparsers:
        return ({}, list(unparsed_arguments))

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Subparser for '{name}' is not an argparse.ArgumentParser")
        try:
            ns, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # Parsing failed (e.g., missing required args); treat as no claims
            ns = None
            remaining = list(unparsed_arguments)
        namespace_map[name] = ns
        remaining_indices_per_parser.append(_remaining_indices(unparsed_arguments, remaining))

    # Compute indices that are remaining for all subparsers
    all_indices = set(range(len(unparsed_arguments)))
    for idx_set in remaining_indices_per_parser:
        all_indices &= idx_set

    # Build list of remaining arguments preserving order
    remaining_args = [unparsed_arguments[i] for i in sorted(all_indices)]

    return (namespace_map, remaining_args)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    # Helper to merge two mapping nodes recursively
    def merge_mapping_nodes(node1, node2):
        if not is_mapping(node1) or not is_mapping(node2):
            # If either is not a mapping, the second node wins
            return node2
        # Merge the mapping values
        merged_value = merge_mapping_values(node1.value, node2.value)
        node1.value = merged_value
        return node1

    # Helper to merge two lists of mapping entries
    def merge_mapping_values(list1, list2):
        # list1 and list2 are lists of (ScalarNode, node) tuples
        result = list1[:]  # shallow copy
        key_index = {k.value: idx for idx, (k, _) in enumerate(result)}
        for key_node, val_node in list2:
            if not hasattr(key_node, 'value'):
                raise TypeError(f'Expected ScalarNode as key, got {type(key_node).__name__}')
            key_str = key_node.value
            if key_str in key_index:
                idx = key_index[key_str]
                existing_key_node, existing_val_node = result[idx]
                if is_mapping(existing_val_node) and is_mapping(val_node):
                    merged_val = merge_mapping_nodes(existing_val_node, val_node)
                    result[idx] = (existing_key_node, merged_val)
                else:
                    # Non-mapping values: last wins
                    result[idx] = (existing_key_node, val_node)
            else:
                result.append((key_node, val_node))
                key_index[key_str] = len(result) - 1
        return result

    if not isinstance(nodes, list):
        raise TypeError(f'Expected list of nodes, got {type(nodes).__name__}')
    result = []
    key_index = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError(f'Each item must be a tuple of (ScalarNode, node), got {item!r}')
        key_node, val_node = item
        if not hasattr(key_node, 'value'):
            raise TypeError(f'Expected ScalarNode as key, got {type(key_node).__name__}')
        key_str = key_node.value
        if key_str in key_index:
            idx = key_index[key_str]
            existing_key_node, existing_val_node = result[idx]
            if is_mapping(existing_val_node) and is_mapping(val_node):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged_val)
            else:
                # Non-mapping values: last wins
                result[idx] = (existing_key_node, val_node)
        else:
            result.append((key_node, val_node))
            key_index[key_str] = len(result) - 1
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation: parser must be an ArgumentParser-like object
    if parser is None:
        raise TypeError("parser must not be None")
    # Check for the internal _actions attribute that argparse uses
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # Each action may have an option_strings attribute
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception as exc:
        # Wrap any unexpected errors in a RuntimeError with context
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator that yields slices of the response list
    def _generator():
        try:
            for start in range(0, len(response), max_results):
                yield response[start:start + max_results]
        except Exception as exc:
            # Re-raise any unexpected exception with context
            raise RuntimeError("Error while paging through response") from exc

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    result = {}
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f"Expected dict, got {type(d).__name__}")
            for key, value in d.items():
                if not isinstance(value, (int, float)):
                    raise TypeError(f"Dictionary values must be numeric, got {type(value).__name__} for key {key!r}")
                result[key] = result.get(key, 0) + value
    except TypeError as e:
        raise
    except Exception as e:
        raise RuntimeError(f"Unexpected error while summing dictionaries: {e}") from e
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        # Treat actual None as a None representation
        if val is None:
            return True
        # Only strings can represent a None value
        if not isinstance(val, str):
            return False
        # Normalize the string: strip whitespace and convert to lowercase
        normalized = val.strip().lower()
        # Common textual representations of None
        none_representations = {"none", "null", "nil", "n/a", "na"}
        return normalized in none_representations
    except Exception:
        # In case of unexpected errors, return False
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate that the input is an ArgumentParser-like object
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        option_strings = getattr(action, 'option_strings', None)
        if option_strings:
            flags.extend(option_strings)

    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("all elements of alphabet must be strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct characters for base conversion")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    sign = ""
    if number < 0:
        sign = "-"
        number = -number

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number > 0:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        digits.reverse()

    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        pad_count = padding - len(digits)
        digits = [alphabet[0]] * pad_count + digits

    return sign + "".join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or str")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")

    def _replace_in_dict(d):
        """Recursively replace keys matching register_value with register_number."""
        for key in list(d.keys()):
            if key == register_value:
                d[register_number] = d.pop(key)
            elif isinstance(d[key], dict):
                _replace_in_dict(d[key])

    _replace_in_dict(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    # Validate inputs
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    # Perform replacement
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise ValueError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    def _rec(sub):
        try:
            for subcls in sub.__subclasses__():
                if subcls not in result:
                    result.add(subcls)
                    _rec(subcls)
        except Exception as exc:
            raise RuntimeError(f"Error retrieving subclasses of {sub.__name__}") from exc
    _rec(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")

    # Alphabet validation
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet contains duplicate symbols")
    for sym in alphabet:
        if not isinstance(sym, str) or len(sym) != 1:
            raise ValueError("alphabet must contain single-character strings")

    # Build mapping from symbol to its numeric value
    mapping = {sym: idx for idx, sym in enumerate(alphabet)}

    # Empty string is treated as zero
    if string == "":
        return 0

    # Convert string to integer
    value = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"character '{ch}' not found in alphabet")
        value = value * base + mapping[ch]

    return value

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    try:
        return re.sub(r"^(['\"])(.*)\1$", r"\2", name)
    except Exception:
        return name

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Resolve absolute path and ensure parent directories exist
    abs_path = os.path.abspath(config_filename)
    dir_path = os.path.dirname(abs_path)
    if dir_path and not os.path.exists(dir_path):
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create directories for '{config_filename}': {exc}") from exc

    # Check for existing file
    if os.path.exists(abs_path):
        if not overwrite:
            raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")
        # If overwrite is True, we will replace the file

    # Write the configuration
    try:
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(abs_path, mode)
    except OSError as exc:
        raise RuntimeError(f"Failed to write configuration to '{config_filename}': {exc}") from exc

    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise TypeError("Matcher cannot be None")

    # Determine name and default based on matcher type
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher sequence must contain at least the variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, str):
        # Split on first colon to separate name and default
        parts = matcher.split(":", 1)
        name = parts[0]
        default = parts[1] if len(parts) == 2 else None
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    if not isinstance(name, str) or not name:
        raise ValueError("Environment variable name must be a non-empty string")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise ValueError(f"Environment variable '{name}' is not set and no default value provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    try:
        if pattern is None:
            raise ValueError("pattern cannot be None")
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if strip:
            pattern = pattern.strip()
        # Escape regex special characters, but keep wildcards
        escaped = re.escape(pattern)
        # Replace escaped wildcards with regex equivalents
        escaped = escaped.replace(r'\*', '.*').replace(r'\?', '.')
        return escaped
    except Exception as e:
        raise ValueError(f"Error generating regex pattern: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    last_output = None
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        # Build the full command string
        full_cmd = cmd
        if args:
            # Quote arguments to handle spaces and special characters
            quoted_args = " ".join(subprocess.list2cmdline([arg]) for arg in args)
            full_cmd = f"{cmd} {quoted_args}"
        if verbose:
            print(f"Running command: {full_cmd}")

        try:
            result = subprocess.run(
                full_cmd,
                shell=True,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stderr=subprocess.DEVNULL if hide_stderr else None
            )
        except OSError as e:
            raise RuntimeError(f"Failed to execute command '{full_cmd}': {e}") from e

        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode,
                full_cmd,
                output=result.stdout,
                stderr=result.stderr
            )
        last_output = result.stdout
    return last_output

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            result = yaml.safe_dump(obj)
        elif isinstance(dumper, type):
            result = yaml.dump(obj, Dumper=dumper)
        else:
            result = dumper(obj)
        try:
            unicode
            if isinstance(result, str):
                result = result.decode('utf-8')
        except NameError:
            pass
        return result
    except Exception:
        return str(obj)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    if x is None:
        raise ValueError("Input x cannot be None.")
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be a number or array-like of numbers.") from e
    mu = 0.2
    sigma = 0.1
    return np.exp(-((x_arr - mu)**2) / (2 * sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    import logging

    configs = {}
    error_records = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f"JSON decode error in file '{filename}': {e}"
                    record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                    error_records.append(record)
                    continue

            # Basic validation: configuration must be a dict
            if not isinstance(data, dict):
                msg = f"Configuration in file '{filename}' is not a JSON object (dict)."
                record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                error_records.append(record)
                continue

            # Resolve environment variables if requested
            if resolve_env:
                data = resolve_env_vars(data)

            # Apply overrides if provided
            if overrides:
                if not isinstance(overrides, dict):
                    msg = f"Overrides provided for file '{filename}' are not a dict."
                    record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                    error_records.append(record)
                    continue
                # Merge overrides into data (shallow)
                data.update(overrides)

            configs[filename] = data

        except FileNotFoundError as e:
            msg = f"File not found: '{filename}'."
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            error_records.append(record)
        except Exception as e:
            # Catch-all for unexpected errors
            msg = f"Unexpected error loading file '{filename}': {e}"
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of handlers; fall back to empty dict if not defined
        handlers = getattr(cls, "_handlers", {})

        # If no specific version requested, return a shallow copy of all handlers
        if protocol_version is None:
            return dict(handlers)

        # Validate that the provided protocol_version is a tuple
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        # Ensure each element in the tuple is an integer (basic sanity check)
        if not all(isinstance(v, int) for v in protocol_version):
            raise TypeError(
                f"All elements of protocol_version must be integers, got {protocol_version}"
            )

        # Return a dictionary containing the handler if the version is supported
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        else:
            return {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable
    if values is None:
        raise TypeError("values must be an iterable of strings")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    # Create an empty Bookmarks instance
    try:
        bookmarks = cls()
    except Exception as e:
        raise RuntimeError(f"Failed to instantiate {cls.__name__}: {e}") from e

    # Helper to add a bookmark to the collection
    def _add(bookmark):
        if hasattr(bookmarks, "add"):
            bookmarks.add(bookmark)
        elif hasattr(bookmarks, "append"):
            bookmarks.append(bookmark)
        elif hasattr(bookmarks, "extend"):
            bookmarks.extend([bookmark])
        else:
            # If no obvious method, try to set an attribute
            try:
                bookmarks.append(bookmark)
            except Exception:
                pass

    for raw in iterator:
        if not isinstance(raw, str):
            raise ValueError(f"Bookmark value must be a string, got {type(raw).__name__}")
        try:
            # Assume a Bookmark class with a from_raw_value constructor
            bookmark = Bookmark.from_raw_value(raw)
        except Exception:
            # Skip invalid entries silently
            continue
        _add(bookmark)

    return bookmarks

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """
    Remove and return the (key, value) pair least frequently used.
    Handles different possible internal structures of an LFU cache.
    Raises KeyError if the cache is empty.
    """
    try:
        # Case 1: typical LFU implementation with freq_map, key_map, and min_freq
        if hasattr(self, "freq_map") and hasattr(self, "key_map") and hasattr(self, "min_freq"):
            if not self.freq_map:
                raise KeyError("Cache is empty.")
            min_freq = self.min_freq
            freq_dict = self.freq_map[min_freq]
            # freq_dict is expected to be an OrderedDict or similar
            key, _ = freq_dict.popitem(last=False)
            value = self.key_map[key][0]
            del self.key_map[key]
            if not freq_dict:
                del self.freq_map[min_freq]
                if self.freq_map:
                    self.min_freq = min(self.freq_map.keys())
                else:
                    self.min_freq = None
            return (key, value)

        # Case 2: simpler implementation with cache and freq dicts
        if hasattr(self, "cache") and hasattr(self, "freq"):
            if not self.cache:
                raise KeyError("Cache is empty.")
            min_freq = min(self.freq.values())
            # Find a key with the minimum frequency
            for k, f in self.freq.items():
                if f == min_freq:
                    key = k
                    break
            value = self.cache.pop(key)
            self.freq.pop(key)
            if self.freq:
                self.min_freq = min(self.freq.values())
            else:
                self.min_freq = None
            return (key, value)

        # If the structure is unknown, raise an informative error
        raise AttributeError("Cache structure not recognized for popitem operation.")
    except Exception as exc:
        raise RuntimeError(f"Error in popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to use an OrderedDict-like structure if available
    try:
        return self._cache.popitem(last=False)
    except (AttributeError, TypeError):
        # Fallback: assume a dict `_cache` and a list `_order` tracking usage
        if not hasattr(self, "_cache") or not hasattr(self, "_order"):
            raise AttributeError("Cache structure not found")
        if not self._order:
            raise KeyError("popitem(): dictionary is empty")
        key = self._order.pop(0)
        try:
            value = self._cache.pop(key)
        except KeyError:
            # Inconsistent state: key missing from cache
            raise KeyError(f"Key {key!r} not found in cache")
        return key, value
    except KeyError:
        # Propagate KeyError if the underlying structure is empty
        raise KeyError("popitem(): dictionary is empty")
    except Exception as exc:
        # Catch-all for unexpected runtime issues
        raise RuntimeError(f"Unexpected error in popitem: {exc}") from exc

