def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            if request.get("public_message"):
                return True
            if request.get("private_message"):
                return True
            if request.get("legacy_payload"):
                return True
            return False

        # Handle object-like requests
        if hasattr(request, "public_message") and getattr(request, "public_message"):
            return True
        if hasattr(request, "private_message") and getattr(request, "private_message"):
            return True
        if hasattr(request, "legacy_payload") and getattr(request, "legacy_payload"):
            return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle None or non-iterable inputs
        if request is None:
            return False

        # If the request is a dictionary, look for typical Matrix keys
        if isinstance(request, dict):
            # Common Matrix request keys
            matrix_keys = {"type", "content", "room_id", "event_id", "sender"}
            # If any of these keys are present, consider it a Matrix request
            return bool(matrix_keys & request.keys())

        # If the request is an object, check for attributes that are common in Matrix requests
        # Use hasattr to avoid AttributeError
        common_attrs = ("type", "content", "room_id", "event_id", "sender")
        for attr in common_attrs:
            if hasattr(request, attr):
                return True

        # If none of the checks passed, it's unlikely to be a Matrix request
        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 without microseconds, e.g. '2023-08-15T13:45:30+00:00'.
    If the datetime is naive, the timezone is omitted.
    """
    try:
        if dt is None:
            raise ValueError("dt cannot be None")
        if not hasattr(dt, "strftime"):
            raise TypeError("dt must be a datetime object")
        # Naive datetime: no timezone information
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            return dt.strftime("%Y-%m-%dT%H:%M:%S")
        # Aware datetime: include timezone offset in +HH:MM format
        base = dt.strftime("%Y-%m-%dT%H:%M:%S")
        offset = dt.strftime("%z")  # e.g. '+0000'
        if offset:
            offset_formatted = offset[:3] + ':' + offset[3:]
            return f"{base}{offset_formatted}"
        return base
    except Exception as e:
        raise ValueError(f"Invalid datetime input: {e}") from e

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Handle None or non-iterable inputs gracefully
    if node is None:
        return {}
    try:
        # Try to iterate over the node to get its children
        children = list(node)
    except Exception:
        # If node is not iterable (e.g., not an Element), return empty dict
        return {}
    result = {}
    for child in children:
        # Ensure the child has a tag attribute (it should for ElementTree elements)
        try:
            tag = child.tag
        except Exception:
            continue
        # Skip children that don't have a tag (e.g., comments or processing instructions)
        if tag is None:
            continue
        # Store the child in the dictionary, overriding duplicates if any
        result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Validate and normalize the document path
    if document_path is not None:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        if document_path == "":
            document_path = None

    # Default path if none provided
    if document_path is None:
        document_path = "/nodeinfo/2.0"

    # Ensure the path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Remove any trailing slash from the base URL to avoid double slashes
    base_url = url.rstrip("/")

    # Construct the full href
    href = base_url + document_path

    # Return the well-known document structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    doc = document.strip()
    if not doc:
        raise ValueError("empty document")

    # Try JSON first
    try:
        json_mod = __import__("json")
        data = json_mod.loads(doc)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        if aliases is None:
            aliases = []
        links = data.get("links", [])
        if links is None:
            links = []
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            ET = __import__("xml.etree.ElementTree")
            root = ET.fromstring(doc)
            # Helper to find elements with any namespace
            def find_any(parent, tag):
                return parent.find(f".//{{*}}{tag}")
            def findall_any(parent, tag):
                return parent.findall(f".//{{*}}{tag}")

            subject_elem = find_any(root, "Subject")
            subject = subject_elem.text if subject_elem is not None else None

            aliases = [e.text for e in findall_any(root, "Alias") if e.text is not None]

            links = []
            for link_elem in findall_any(root, "Link"):
                link = {}
                for attr in ("rel", "type", "href", "template"):
                    if attr in link_elem.attrib:
                        link[attr] = link_elem.attrib[attr]
                if link:
                    links.append(link)

            return {"subject": subject, "aliases": aliases, "links": links}
        except Exception as exc:
            raise ValueError("Invalid webfinger document") from exc

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string containing '@'")
    try:
        _, domain = handle.split('@', 1)
    except Exception:
        raise ValueError("handle must be in the form local@domain")
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        urllib_request = __import__('urllib.request')
        urllib_error = __import__('urllib.error')
        json_mod = __import__('json')
    except Exception:
        return None
    try:
        with urllib_request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            content = resp.read().decode('utf-8')
            try:
                return json_mod.loads(content)
            except Exception:
                return None
    except (urllib_error.HTTPError, urllib_error.URLError, Exception):
        return None

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : str or iterable of str
        Directory or directories to search for files.
    spec_option : str
        Glob pattern to match file names (e.g., '*.ini').

    Returns
    -------
    list of str
        Full paths of files that match the pattern in the given directories.
    """
    import os
    import glob

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string pattern")

    # If spec_option is empty, match all files
    pattern = spec_option if spec_option else "*"

    matched_files = []
    for d in dirs:
        if not isinstance(d, str):
            continue  # skip non-string entries
        if not os.path.isdir(d):
            continue  # skip non-existent directories
        try:
            # Use glob to find matching files
            for path in glob.glob(os.path.join(d, pattern)):
                if os.path.isfile(path):
                    matched_files.append(os.path.abspath(path))
        except Exception:
            # Skip directories that cause errors
            continue

    return sorted(matched_files)

