    """Gets the workspace manager."""
    try:
        if not hasattr(cls, "_workspace_manager") or cls._workspace_manager is None:
            # Define a simple manager class
            class _WorkspaceManager:
                def __init__(self):
                    self.workspaces = {}
                def add_workspace(self, name, data):
                    if name in self.workspaces:
                        raise ValueError(f"Workspace '{name}' already exists.")
                    self.workspaces[name] = data
                def get_workspace(self, name):
                    return self.workspaces.get(name)
                def list_workspaces(self):
                    return list(self.workspaces.keys())
            cls._workspace_manager = _WorkspaceManager()
        return cls._workspace_manager
    except Exception as e:
        raise RuntimeError("Failed to get workspace manager") from e

def plugins_manager(cls):
    """Gets the plugin manager. """
    try:
        if not hasattr(cls, "_plugin_manager") or cls._plugin_manager is None:
            # Lazy initialization of the plugin manager
            cls._plugin_manager = PluginManager()
        return cls._plugin_manager
    except Exception as exc:
        raise RuntimeError("Unable to retrieve plugin manager") from exc

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("yaml_file must be provided")

    try:
        import yaml
    except Exception as exc:
        raise IRValidatorException(f"Failed to import yaml module: {exc}") from exc

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"File not found: {yaml_file}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Error loading YAML file '{yaml_file}': {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a top-level dictionary")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', None)
        if spec is None:
            return defaults
        if not isinstance(spec, dict):
            raise TypeError("spec must be a dictionary")
        env_source = getattr(self, 'env', {})
        config_source = getattr(self, 'config', {})
        for arg, arg_spec in spec.items():
            # If the spec for this argument is a dictionary, look for keys
            if isinstance(arg_spec, dict):
                # Use explicit default if provided
                if 'default' in arg_spec:
                    defaults[arg] = arg_spec['default']
                    continue
                # Try environment variable
                env_key = arg_spec.get('env')
                if env_key and isinstance(env_source, dict):
                    env_val = env_source.get(env_key)
                    if env_val is not None:
                        defaults[arg] = env_val
                        continue
                # Try configuration source
                config_key = arg_spec.get('config')
                if config_key and isinstance(config_source, dict):
                    config_val = config_source.get(config_key)
                    if config_val is not None:
                        defaults[arg] = config_val
                        continue
                # If nothing found, set to None
                defaults[arg] = None
            else:
                # If the spec itself is a value, treat it as the default
                defaults[arg] = arg_spec
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    try:
        # Attempt to retrieve a pre-defined mapping of deprecated arguments.
        # If the attribute does not exist or is not a dict, fall back to an empty dict.
        deprecated = getattr(self, 'deprecated_args', {})
        if isinstance(deprecated, dict):
            return deprecated
        return {}
    except Exception:
        # In case of any unexpected error, return an empty dictionary to avoid breaking callers.
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Basic input validation
        if cli_args is None:
            cli_args = {}
        if answer_file_args is None:
            answer_file_args = {}

        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Determine deprecated arguments mapping if available
        deprecated_map = {}
        if hasattr(self, "deprecated_args"):
            # Expecting a dict mapping deprecated arg names to new arg names
            try:
                deprecated_map = dict(self.deprecated_args)
            except Exception:
                # If conversion fails, ignore deprecation handling
                deprecated_map = {}

        # Helper to process a single argument source
        def _process_source(source_name, args_dict):
            for arg_name in list(args_dict.keys()):
                if not isinstance(arg_name, str):
                    continue  # skip non-string keys
                if arg_name in deprecated_map:
                    new_name = deprecated_map[arg_name]
                    msg = f"Argument '{arg_name}' is deprecated"
                    if new_name:
                        msg += f" and will be replaced by '{new_name}'"
                    msg += "."
                    print(msg)

        # Check for deprecation in CLI args
        _process_source("CLI", cli_args)

        # Check for deprecation in answer file args
        _process_source("Answer file", answer_file_args)

        # If the same deprecated argument appears in both sources, warn about precedence
        for arg_name in deprecated_map:
            in_cli = arg_name in cli_args
            in_ans = arg_name in answer_file_args
            if in_cli and in_ans:
                print(f"Deprecated argument '{arg_name}' is defined in both CLI and answer file; "
                      f"CLI value will take precedence.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Ensure the parser attribute exists
    parser = getattr(self, "parser", None)
    if parser is None:
        raise AttributeError("The object does not have a 'parser' attribute")

    # Find the subparser corresponding to the command
    subparser = None
    try:
        actions = getattr(parser, "_actions", [])
    except Exception as exc:
        raise AttributeError("Parser object does not have a '_actions' attribute") from exc

    for action in actions:
        # Subparsers actions expose a 'choices' dict mapping command names to subparsers
        if hasattr(action, "choices") and isinstance(action.choices, dict):
            if command_name in action.choices:
                subparser = action.choices[command_name]
                break

    if subparser is None:
        raise ValueError(f"Command '{command_name}' not found in parser subcommands")

    # Collect all option strings from the subparser
    options = []
    try:
        sub_actions = getattr(subparser, "_actions", [])
    except Exception as exc:
        raise AttributeError("Subparser object does not have a '_actions' attribute") from exc

    for action in sub_actions:
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            options.extend(option_strings)

    return options

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Define a set of argument names that are considered silent.
    silent_flags = {"--quiet", "--silent", "-q", "-s"}
    try:
        if args is None:
            return []
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of argument names")
        # Filter out arguments that match the silent flags.
        silent_args = [arg for arg in args if isinstance(arg, str) and arg in silent_flags]
        return silent_args
    except Exception:
        # In case of any unexpected error, return an empty list to avoid breaking the caller.
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Ensure the class defines required_args
    if not hasattr(self, "required_args"):
        raise AttributeError("The object does not define 'required_args'")

    required = getattr(self, "required_args")
    if not hasattr(required, "__iter__"):
        raise TypeError("'required_args' must be an iterable of argument names")

    # Find any missing required arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Validate inputs
    if not isinstance(options_spec, list):
        raise TypeError("options_spec must be a list of option specifications")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of received arguments")

    required_names = set()

    for opt in options_spec:
        if not isinstance(opt, dict):
            continue  # skip invalid option spec entries

        name = opt.get("name")
        if not name:
            continue  # skip options without a name

        cond = opt.get("required_when")
        if cond is None:
            continue  # no conditional requirement

        try:
            # If the condition is a callable, invoke it with args and command_name
            if callable(cond):
                match = cond(args, command_name)
            else:
                # Assume a string expression; evaluate it in a safe context
                # Provide only 'args' and 'command_name' to the eval environment
                match = eval(cond, {}, {"args": args, "command_name": command_name})
        except Exception:
            # If evaluation fails, treat the condition as not matched
            match = False

        if match:
            required_names.add(name)

    return list(required_names)

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected to be a dictionary mapping
                 argument names to their values.
    :raises TypeError: If `args` is not a dictionary.
    :raises ValueError: If any argument value exceeds its specified maximum length.
    :return: True if all arguments satisfy their length constraints.
    """
    # Ensure args is a dictionary
    if args is None:
        return True
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary of argument names to values")

    # Retrieve the mapping of argument names to maximum allowed lengths.
    # If the attribute is missing or not a dict, skip validation.
    max_lengths = getattr(self, "max_lengths", None)
    if not isinstance(max_lengths, dict):
        return True

    for key, value in args.items():
        # Skip keys that have no length constraint
        if key not in max_lengths:
            continue

        max_len = max_lengths[key]
        # Validate that the maximum length is a non-negative integer
        if not isinstance(max_len, int) or max_len < 0:
            continue

        # Skip None values or values that cannot be measured by len()
        if value is None:
            continue
        try:
            length = len(value)
        except Exception:
            continue

        if length > max_len:
            raise ValueError(
                f"Argument '{key}' length {length} exceeds maximum allowed {max_len}"
            )

    return True

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    :raises TypeError: If args is not a dict.
    :raises ValueError: If an argument value is not within its defined choices.
    :return: True if all choice arguments are valid.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    # Retrieve the argument definitions; if not present, nothing to validate
    arg_defs = getattr(self, "arguments", {})
    if not isinstance(arg_defs, dict):
        # If arguments is not a dict, we cannot perform validation
        return True

    for arg_name, arg_def in arg_defs.items():
        # Skip if the definition is not a dict or has no choices
        if not isinstance(arg_def, dict) or "choices" not in arg_def:
            continue

        # Skip validation if the argument was not supplied
        if arg_name not in args:
            continue

        value = args[arg_name]
        choices = arg_def["choices"]

        # If the value is an iterable (but not a string), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v}. "
                        f"Expected one of {choices}."
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Expected one of {choices}."
                )

    return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        try:
            # Extract min, max, and value from args
            if isinstance(args, dict):
                if not all(k in args for k in ("min", "max", "value")):
                    raise ValueError("Dictionary must contain 'min', 'max', and 'value' keys.")
                min_val, max_val, value = args["min"], args["max"], args["value"]
            elif isinstance(args, (list, tuple)):
                if len(args) != 3:
                    raise ValueError("Iterable must contain exactly three elements: min, max, value.")
                min_val, max_val, value = args
            else:
                raise TypeError("args must be a dict or a list/tuple of length 3.")

            # Validate that min, max, and value are numeric
            if not all(isinstance(v, (int, float)) for v in (min_val, max_val, value)):
                raise TypeError("min, max, and value must be numeric.")

            # Ensure min is not greater than max
            if min_val > max_val:
                raise ValueError("Minimum value cannot be greater than maximum value.")

            # Check if value is within the inclusive range
            if not (min_val <= value <= max_val):
                raise ValueError(f"Value {value} is not between {min_val} and {max_val}.")

            return True
        except Exception as exc:
            # Provide a clear error message while preserving the original exception context
            raise ValueError(f"Invalid arguments: {exc}") from exc

def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        # Validate input types
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict

        # Normalize extra_vars to an iterable of strings
        if isinstance(extra_vars, dict):
            items = list(extra_vars.items())
        elif isinstance(extra_vars, (list, tuple)):
            items = extra_vars
        elif isinstance(extra_vars, str):
            items = [extra_vars]
        else:
            raise TypeError("extra_vars must be a dict, list, tuple, or string")

        def _parse_value(val):
            """Attempt to convert string to bool, int, float, or keep as string."""
            if not isinstance(val, str):
                return val
            val = val.strip()
            # Strip surrounding quotes
            if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                val = val[1:-1]
            lower = val.lower()
            if lower == "true":
                return True
            if lower == "false":
                return False
            # Integer
            if val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                try:
                    return int(val)
                except ValueError:
                    pass
            # Float
            try:
                return float(val)
            except ValueError:
                pass
            return val

        for item in items:
            # If item is a tuple (key, value) from dict
            if isinstance(item, tuple) and len(item) == 2:
                key, value = item
            elif isinstance(item, str):
                if "=" not in item:
                    # Skip items without '='
                    continue
                key, value = item.split("=", 1)
            else:
                # Unsupported item type; skip
                continue

            key = key.strip()
            if not key:
                continue
            parsed_value = _parse_value(value)
            vars_dict[key] = parsed_value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    # Validate playbook path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    cmd = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non‑negative integer")
        cmd.append("-" + "v" * verbose)

    # Additional ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            flag = f"--{key.replace('_', '-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Append the playbook path
    cmd.append(playbook_path)

    # Optional: log the command (if the plugin provides a log method)
    try:
        log_method = getattr(ir_plugin, "log", None)
        if callable(log_method):
            log_method(f"Running command: {' '.join(cmd)}")
    except Exception:
        pass  # ignore logging errors

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except subprocess.CalledProcessError as exc:
        # Include stderr in the exception message for debugging
        raise RuntimeError(
            f"ansible-playbook failed with exit code {exc.returncode}:\n{exc.stderr}"
        ) from exc

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        def _convert_value(val):
            # If already a non-string type, return as is
            if not isinstance(val, str):
                return val
            # Strip whitespace
            s = val.strip()
            # Empty string stays empty
            if s == '':
                return s
            # Boolean conversion
            low = s.lower()
            if low in ('true', 'false'):
                return low == 'true'
            # Integer conversion
            try:
                if s.isdigit() or (s[0] in '+-' and s[1:].isdigit()):
                    return int(s)
            except Exception:
                pass
            # Float conversion
            try:
                return float(s)
            except Exception:
                pass
            # List conversion (comma separated)
            if ',' in s:
                parts = [p.strip() for p in s.split(',')]
                # Convert each part recursively
                return [_convert_value(p) for p in parts]
            # Default: return original string
            return s

        # Iterate over the dictionary and convert values
        for key, value in list(values_dict.items()):
            try:
                values_dict[key] = _convert_value(value)
            except Exception:
                # If any unexpected error occurs, leave the original value
                continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    try:
        # Ensure plugin_dir is a string path
        if not isinstance(plugin_dir, str):
            return {}
        # Import os and json dynamically to avoid explicit import statements
        os = __import__('os')
        json = __import__('json')
        # Check if directory exists
        if not os.path.isdir(plugin_dir):
            return {}
        # Look for plugin spec file (plugin.json)
        spec_path = os.path.join(plugin_dir, 'plugin.json')
        if not os.path.isfile(spec_path):
            # If plugin.json not found, try plugin.yaml
            spec_path = os.path.join(plugin_dir, 'plugin.yaml')
            if not os.path.isfile(spec_path):
                return {}
        # Read the spec file
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
        # Parse JSON or YAML
        if spec_path.endswith('.json'):
            try:
                data = json.loads(content)
            except Exception:
                return {}
        else:
            # Simple YAML parsing: assume key: value pairs, no nested structures
            data = {}
            for line in content.splitlines():
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if ':' in line:
                    key, val = line.split(':', 1)
                    data[key.strip()] = val.strip()
        # Flatten the dictionary
        if isinstance(data, dict):
            return _flatten(data)
        else:
            return {}
    except Exception:
        # In case of any unexpected error, return empty dict
        return {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        # Use a standard environment variable name for the config path
        env_var = "CONFIG_PATH"
        # If the variable is not already set, assign a sensible default
        if os.getenv(env_var) is None:
            # Default to a config file named 'config.yaml' in the current working directory
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError to provide context
        raise RuntimeError(f"Failed to set environment variable '{env_var}': {exc}") from exc
